window.NTI=window.NTI||{};(window.NTI.docs=window.NTI.docs||{})["kubernetes-22-services-amp-br-networking"]={"html":"Services &amp; Networking Deep Dive — Kubernetes Book 03\n\n\n<a href=\"#toc\">▤ TOC</a>\n\n\n<div class=\"page cover\">\n<div class=\"orb\"></div>\n<div class=\"orb\"></div>\n<div class=\"wheel\">🌐</div>\n<h1 id=\"services-amp-networking\">SERVICES &amp;<br />NETWORKING</h1>\n<div class=\"sub\">Book 03 of the series — from NodePort demo tricks to production traffic: LoadBalancer, Ingress &amp; TLS termination, the controller ecosystem, NetworkPolicy zero-trust, CoreDNS internals, and the Gateway API that comes next.</div>\n<div class=\"row\">\n<div class=\"glass\">⚖️ LoadBalancer<small>cloud entry point</small></div>\n<div class=\"glass\">🚦 Ingress<small>host &amp; path routing</small></div>\n<div class=\"glass\">🔐 TLS<small>terminate at the edge</small></div>\n<div class=\"glass\">🧭 Controllers<small>nginx · traefik…</small></div>\n</div>\n<div class=\"row\">\n<div class=\"glass\">🚧 NetworkPolicy<small>default-deny</small></div>\n<div class=\"glass\">📮 CoreDNS<small>service discovery</small></div>\n<div class=\"glass\">🛣️ Gateway API<small>the successor</small></div>\n<div class=\"glass\">🧪 4 Labs<small>prove it hands-on</small></div>\n</div>\n<div class=\"ver\">K8S KNOWLEDGE BASE · BOOK 03 · CONTINUES BOOKS 01–02 · 2026</div>\n</div>\n\n\n<div class=\"page\">\n<div class=\"pghead\"><span class=\"chip\">📖</span><h2 id=\"contents-click-any-row\">Contents — click any row</h2><span class=\"dbadge\">7 parts · 22 chapters</span></div>\n<div class=\"tocgrid\">\n<div class=\"tocpart\">Part I · Beyond NodePort</div>\n<a href=\"#ch01\"><span class=\"cb\"></span><span class=\"tnum\">CH 01</span>The Exposition Ladder<span class=\"dots\"></span><span class=\"tp\">p.3</span></a>\n<a href=\"#ch02\"><span class=\"cb\"></span><span class=\"tnum\">CH 02</span>LoadBalancer — The Cloud Type<span class=\"dots\"></span><span class=\"tp\">p.4</span></a>\n<a href=\"#ch03\"><span class=\"cb\"></span><span class=\"tnum\">CH 03</span>The Problem Ingress Solves<span class=\"dots\"></span><span class=\"tp\">p.5</span></a>\n<div class=\"tocpart\">Part II · Ingress</div>\n<a href=\"#ch04\"><span class=\"cb\"></span><span class=\"tnum\">CH 04</span>Ingress &amp; IngressClass<span class=\"dots\"></span><span class=\"tp\">p.6</span></a>\n<a href=\"#ch05\"><span class=\"cb\"></span><span class=\"tnum\">CH 05</span>Host &amp; Path Routing<span class=\"dots\"></span><span class=\"tp\">p.7</span></a>\n<a href=\"#ch06\"><span class=\"cb\"></span><span class=\"tnum\">CH 06</span>TLS Termination<span class=\"dots\"></span><span class=\"tp\">p.8</span></a>\n<a href=\"#ch07\"><span class=\"cb\"></span><span class=\"tnum\">CH 07</span>Ingress Controllers<span class=\"dots\"></span><span class=\"tp\">p.9</span></a>\n<div class=\"tocpart\">Part III · NetworkPolicy</div>\n<a href=\"#ch08\"><span class=\"cb\"></span><span class=\"tnum\">CH 08</span>The Default-Allow World<span class=\"dots\"></span><span class=\"tp\">p.10</span></a>\n<a href=\"#ch09\"><span class=\"cb\"></span><span class=\"tnum\">CH 09</span>NetworkPolicy — Ingress Rules<span class=\"dots\"></span><span class=\"tp\">p.11</span></a>\n<a href=\"#ch10\"><span class=\"cb\"></span><span class=\"tnum\">CH 10</span>Egress + The Default-Deny Playbook<span class=\"dots\"></span><span class=\"tp\">p.12</span></a>\n<div class=\"tocpart\">Part IV · DNS</div>\n<a href=\"#ch11\"><span class=\"cb\"></span><span class=\"tnum\">CH 11</span>CoreDNS — Discovery Internals<span class=\"dots\"></span><span class=\"tp\">p.13</span></a>\n<a href=\"#ch12\"><span class=\"cb\"></span><span class=\"tnum\">CH 12</span>dnsPolicy &amp; DNS Debugging<span class=\"dots\"></span><span class=\"tp\">p.14</span></a>\n<div class=\"tocpart\">Part V · What's Next</div>\n<a href=\"#ch13\"><span class=\"cb\"></span><span class=\"tnum\">CH 13</span>Gateway API — The Successor<span class=\"dots\"></span><span class=\"tp\">p.15</span></a>\n<div class=\"tocpart\">Part VI · Labs</div>\n<a href=\"#lab1\"><span class=\"cb\"></span><span class=\"tnum\">LAB 1</span>Path Routing via Ingress<span class=\"dots\"></span><span class=\"tp\">p.16</span></a>\n<a href=\"#lab2\"><span class=\"cb\"></span><span class=\"tnum\">LAB 2</span>TLS on an Ingress<span class=\"dots\"></span><span class=\"tp\">p.17</span></a>\n<a href=\"#lab3\"><span class=\"cb\"></span><span class=\"tnum\">LAB 3</span>Default-Deny → Selective Allow<span class=\"dots\"></span><span class=\"tp\">p.18</span></a>\n<a href=\"#lab4\"><span class=\"cb\"></span><span class=\"tnum\">LAB 4</span>DNS Debugging from Inside a Pod<span class=\"dots\"></span><span class=\"tp\">p.19</span></a>\n<div class=\"tocpart\">Part VII · Prove It</div>\n<a href=\"#quiz\"><span class=\"cb\"></span><span class=\"tnum\">QUIZ</span>Self-Check Quiz<span class=\"dots\"></span><span class=\"tp\">p.20</span></a>\n<a href=\"#key\"><span class=\"cb\"></span><span class=\"tnum\">KEY</span>Answer Key + Scoring<span class=\"dots\"></span><span class=\"tp\">p.21</span></a>\n<a href=\"#gloss\"><span class=\"cb\"></span><span class=\"tnum\">GLOSS</span>Glossary<span class=\"dots\"></span><span class=\"tp\">p.22</span></a>\n<a href=\"#cheat\"><span class=\"cb\"></span><span class=\"tnum\">CHEAT</span>One-Page Cheat Sheet<span class=\"dots\"></span><span class=\"tp\">p.23</span></a>\n<a href=\"#finale\"><span class=\"cb\"></span><span class=\"tnum\">FINALE</span>Where to Next → Book 04<span class=\"dots\"></span><span class=\"tp\">p.24</span></a>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Assumes Books 01–02.</b> You know ClusterIP/NodePort and the virtual-IP trick (Book 01 · CH 25–28), service DNS basics (Book 01 · CH 12), and Secrets — including the <code>tls</code> type (Book 02 · CH 05–07). This book takes traffic from \"port 30080 and pray\" to production-grade entry and zero-trust inside.</div></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span>◀ cover · start ▶</span><span>Page 2</span></div>\n</div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 01</span><h2 id=\"the-exposition-ladder\">🪜 The Exposition Ladder</h2><span class=\"dbadge\">🟢 4 MIN</span></div>\n<p>Three ways to reach a Service, each one delegating to the one below it. Book 01 showed the first two — this chapter frames them as a <b>ladder</b>, because every rung exists to fix the rung beneath.</p>\n<div class=\"zone zone-net\">\n<div class=\"zlabel\">The ladder — top is for humans, bottom is machinery</div>\n<div class=\"rowc\"><div class=\"nb c-violet\">⚖️ LoadBalancer<small>cloud LB · one public IP</small></div></div>\n<div class=\"stem\"></div><div class=\"barwrap\"><div class=\"hbar bar2\"></div></div>\n<div class=\"cols\">\n<div class=\"col\"><div class=\"stub\"></div><div class=\"nb c-sky\">🚪 NodePort<small>30000–32767 on every node</small></div></div>\n<div class=\"col\"><div class=\"stub\"></div><div class=\"nb c-emerald\">🕸️ ClusterIP<small>internal virtual IP only</small></div></div>\n</div>\n<p>LB forwards to NodePorts · NodePorts forward through kube-proxy DNAT to Pods — each rung hides the one below</p>\n</div>\n<div class=\"table-scroll\"><table>\n<tr><th>Rung</th><th>Reach</th><th>Kills it</th></tr>\n<tr><td><b>ClusterIP</b></td><td>inside the cluster only</td><td>literally unreachable from outside</td></tr>\n<tr><td><b>NodePort</b></td><td>any node's IP + a high port</td><td>raw ports, users hate <code>:30080</code>, no LB across nodes, no TLS story</td></tr>\n<tr><td><b>LoadBalancer</b></td><td>one cloud IP per Service</td><td>$$$ per Service — 10 services = 10 LB bills, and still no path routing</td></tr>\n</table></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> the ladder is a delegation chain — <i>LoadBalancer → NodePort → ClusterIP → Pods</i>. NodePort solved reachability but not usability; LoadBalancer solved usability but not your cloud invoice. The next rung up — <b>Ingress</b> — fixes the invoice.</div></div>\n<p>⏭️ First, the cloud rung in detail — <a href=\"#ch02\">CH 02: LoadBalancer</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#toc\">▤ TOC</a> · <a href=\"#ch02\">next ▶</a></span><span>Page 3</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 02</span><h2 id=\"loadbalancer-the-cloud-type\">⚖️ LoadBalancer — The Cloud Type</h2><span class=\"dbadge\">🟡 5 MIN</span></div>\n<div class=\"term\"><span class=\"c\">apiVersion</span>: v1\n<span class=\"c\">kind</span>: Service\n<span class=\"c\">metadata</span>:\n  <span class=\"c\">name</span>: web\n<span class=\"c\">spec</span>:\n  <span class=\"c\">type</span>: <span class=\"y\">LoadBalancer</span>     <span class=\"g\"># on a supported platform</span>\n  <span class=\"c\">selector</span>: { <span class=\"c\">app</span>: web }\n  <span class=\"c\">ports</span>:\n  - <span class=\"c\">port</span>: <span class=\"y\">80</span>\n    <span class=\"c\">targetPort</span>: <span class=\"y\">8080</span></div>\n<h3 id=\"what-actually-happens-on-apply\">🌩️ What actually happens on apply</h3>\n<div class=\"zone zone-cp\">\n<div class=\"rowc\"><div class=\"nb c-blue\">API Server<small>Service created</small></div><span class=\"harr\">──►</span><div class=\"nb c-indigo\">Cloud LoadBalancer Controller<small>watches Services</small></div></div>\n<div class=\"dn\">▼</div>\n<div class=\"rowc\"><div class=\"kchip\">☁️ provisions ELB / Azure LB / GCLB<small> public IP assigned</small></div><span class=\"harr\">──►</span><div class=\"nb c-sky\">LB → NodePorts<small>of every healthy node</small></div><span class=\"harr\">──►</span><div class=\"pod\">🫛 Pods</div></div>\n</div>\n<div class=\"term\"><span class=\"p\">$</span> kubectl get svc web\n<span class=\"y\">NAME  TYPE          EXTERNAL-IP  PORT(S)</span>\nweb   LoadBalancer  <span class=\"r\">&lt;pending&gt;</span>  80:31234/TCP  <span class=\"g\"># provisioning…</span>\nweb   LoadBalancer  <span class=\"p\">203.0.113.7</span>  80:31234/TCP  <span class=\"g\"># ready ✓</span></div>\n<ul>\n<li>🔍 The NodePort in the port column is the tell: <b>LoadBalancer is NodePort underneath</b> — the LB just fronts it</li>\n<li>🏠 <b>No cloud?</b> On minikube run <code>minikube tunnel</code> and the <code>&lt;pending&gt;</code> becomes a real local IP; bare metal can run <b>MetalLB</b> to play the cloud controller's role</li>\n<li>💰 <b>Cost model:</b> one cloud LB <i>per Service</i> that asks — this is exactly the tax CH 03 abolishes</li>\n</ul>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b><code>&lt;pending&gt;</code> forever?</b> Either your platform has no LB controller (plain kubeadm, kind, Docker Desktop) or the cloud quota/IAM is blocking. The Service is never \"broken\" — the environment just can't fulfill the request.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> <i>LoadBalancer = NodePort + a cloud wallet</i>. Great for the one true edge of an app; terrible as a per-microservice habit.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#ch01\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch03\">next ▶</a></span><span>Page 4</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 03</span><h2 id=\"the-problem-ingress-solves\">💡 The Problem Ingress Solves</h2><span class=\"dbadge\">🟢 4 MIN</span></div>\n<div class=\"grid2\">\n<div class=\"card\">\n<div class=\"zlabel\">❌ Naive: one LB per Service</div>\n<div class=\"mtree\"><span class=\"r\">cloud LB #1 → web-svc</span>\n<span class=\"r\">cloud LB #2 → api-svc</span>\n<span class=\"r\">cloud LB #3 → admin-svc</span>\n<span class=\"r\">cloud LB #4 → docs-svc</span>\n<span class=\"g\">$ × 4 · TLS certs × 4 · WAF × 4\n· no shared path rules · bill pain</span></div>\n</div>\n<div class=\"card\">\n<div class=\"zlabel\">✅ Ingress: one edge, many routes</div>\n<div class=\"mtree\">cloud LB <span class=\"u\">(just 1)</span>\n└── Ingress controller\n    ├── shop.example.com      → web-svc\n    ├── example.com/api       → api-svc\n    ├── example.com/admin     → admin-svc\n    └── docs.example.com      → docs-svc\n<span class=\"g\">1 bill · 1 TLS cert · L7 rules as YAML</span></div>\n</div>\n</div>\n<p>Ingress is <b>Layer-7</b> awareness at the edge: it reads the HTTP <b>hostname</b> and <b>path</b> and routes accordingly — something NodePort/LoadBalancer (dumb TCP forwards) fundamentally cannot do.</p>\n<div class=\"rowc\">\n<div class=\"kchip\">🌍 https://shop.example.com</div><span class=\"harr\">┐</span>\n<div class=\"kchip\">🌍 https://example.com/api</div><span class=\"harr\">┤</span><span class=\"harr\">──►</span>\n<div class=\"nb c-violet\">🚦 Ingress<small>1 LB · 1 TLS</small></div><span class=\"harr\">──►</span>\n<div class=\"pod\">web</div><div class=\"pod\">api</div><div class=\"pod\">docs</div>\n</div>\n<div class=\"callout co-fun\"><span class=\"ico\">😄</span><div><b>Apartment update:</b> LoadBalancer built every visitor their own private bridge to one apartment. Ingress hired a <b>front desk</b>: one entrance, a directory, and it reads the address on your letter to send you to the right apartment.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> Ingress consolidates N cloud load balancers into one, and upgrades dumb port-forwarding into <b>hostname/path-aware HTTP routing</b> — declared as plain YAML, versioned with your app.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#ch02\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch04\">next ▶</a></span><span>Page 5</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 04</span><h2 id=\"ingress-amp-ingressclass\">🚦 Ingress &amp; IngressClass</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Two facts before any YAML: <b>(1)</b> an Ingress is just a rulebook — <b>nothing forwards traffic until a controller reads it</b>; <b>(2)</b> <code>ingressClassName</code> declares <i>which</i> controller owns it.</p>\n<div class=\"term\"><span class=\"c\">apiVersion</span>: networking.k8s.io/v1\n<span class=\"c\">kind</span>: Ingress\n<span class=\"c\">metadata</span>:\n  <span class=\"c\">name</span>: main\n<span class=\"c\">spec</span>:\n  <span class=\"c\">ingressClassName</span>: <span class=\"y\">nginx</span>     <span class=\"g\"># which referee handles this rulebook</span>\n  <span class=\"c\">rules</span>:\n  - <span class=\"c\">host</span>: <span class=\"m\">demo.local</span>\n    <span class=\"c\">http</span>:\n      <span class=\"c\">paths</span>:\n      - <span class=\"c\">path</span>: <span class=\"m\">/</span>\n        <span class=\"c\">pathType</span>: <span class=\"y\">Prefix</span>\n        <span class=\"c\">backend</span>:\n          <span class=\"c\">service</span>: { <span class=\"c\">name</span>: web, <span class=\"c\">port</span>: { <span class=\"c\">number</span>: <span class=\"y\">80</span> } }</div>\n<div class=\"table-scroll\"><table>\n<tr><th>Piece</th><th>Role</th><th>Apartment translation</th></tr>\n<tr><td><code>Ingress</code></td><td>the routing rulebook ( declarative YAML)</td><td>the front-desk directory</td></tr>\n<tr><td><code>IngressClass</code></td><td>named type of controller; routes rulebooks to referees</td><td>which security firm staffs the desk</td></tr>\n<tr><td><b>Ingress Controller</b></td><td>actual reverse proxy watching Ingress objects</td><td>the desk itself</td></tr>\n</table></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>The silent trap:</b> <code>kubectl apply</code> an Ingress with <b>no controller installed</b> and you get <b>zero errors</b> — the object is stored, accepted, and does nothing. The classic symptom: Ingress exists, <code>get ingress</code> shows no ADDRESS, curl hangs. Check <code>kubectl get ingressclass</code> first.</div></div>\n<div class=\"term mini\"><span class=\"g\"># minikube — one command installs ingress-nginx + the \"nginx\" IngressClass:</span>\n<span class=\"p\">$</span> minikube addons enable ingress\n<span class=\"p\">$</span> kubectl get pods -n ingress-nginx\n<span class=\"g\">ingress-nginx-controller-xxxxx  1/1  Running</span></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Rulebook vs referee:</b> the Ingress <i>object</i> states intent; the <i>controller</i> is the running reverse proxy that enforces it. Kubernetes ships the grammar — you supply the proxy.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#ch03\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch05\">next ▶</a></span><span>Page 6</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 05</span><h2 id=\"host-amp-path-routing\">🛣️ Host &amp; Path Routing</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>The full routing surface: multiple <b>hosts</b>, each with multiple <b>paths</b>, each pointing at its own Service.</p>\n<div class=\"term\"><span class=\"c\">spec</span>:\n  <span class=\"c\">ingressClassName</span>: <span class=\"y\">nginx</span>\n  <span class=\"c\">rules</span>:\n  - <span class=\"c\">host</span>: <span class=\"m\">shop.example.com</span>            <span class=\"g\"># name-based virtual host</span>\n    <span class=\"c\">http</span>:\n      <span class=\"c\">paths</span>:\n      - <span class=\"c\">path</span>: <span class=\"m\">/api</span>\n        <span class=\"c\">pathType</span>: <span class=\"y\">Prefix</span>\n        <span class=\"c\">backend</span>: { <span class=\"c\">service</span>: { <span class=\"c\">name</span>: api-svc, <span class=\"c\">port</span>: { <span class=\"c\">number</span>: <span class=\"y\">80</span> } } }\n      - <span class=\"c\">path</span>: <span class=\"m\">/</span>\n        <span class=\"c\">pathType</span>: <span class=\"y\">Prefix</span>\n        <span class=\"c\">backend</span>: { <span class=\"c\">service</span>: { <span class=\"c\">name</span>: web-svc, <span class=\"c\">port</span>: { <span class=\"c\">number</span>: <span class=\"y\">80</span> } } }\n  - <span class=\"c\">host</span>: <span class=\"m\">docs.example.com</span>             <span class=\"g\"># second host, same edge</span>\n    <span class=\"c\">http</span>:\n      <span class=\"c\">paths</span>:\n      - <span class=\"c\">path</span>: <span class=\"m\">/</span>\n        <span class=\"c\">pathType</span>: <span class=\"y\">Prefix</span>\n        <span class=\"c\">backend</span>: { <span class=\"c\">service</span>: { <span class=\"c\">name</span>: docs-svc, <span class=\"c\">port</span>: { <span class=\"c\">number</span>: <span class=\"y\">80</span> } } }</div>\n<div class=\"table-scroll\"><table>\n<tr><th>pathType</th><th>Matches</th><th><code>/api/v1</code>?</th></tr>\n<tr><td><code>Prefix</code></td><td>path <i>and everything under it</i>, by segments</td><td>✅ yes (for <code>/api</code>)</td></tr>\n<tr><td><code>Exact</code></td><td>only the literal path</td><td>❌ no — only <code>/api</code> itself</td></tr>\n<tr><td><code>ImplementationSpecific</code></td><td>controller decides (nginx treats it like Prefix + regex support)</td><td>controller-defined</td></tr>\n</table></div>\n<ul>\n<li>🧮 <b>Order doesn't matter</b> — nginx sorts by longest-prefix, so <code>/api</code> wins over <code>/</code> no matter where it's listed</li>\n<li>🎯 No host field at all = catch-all for <b>every</b> hostname hitting the edge (handy, but easy to shadow specific rules — be deliberate)</li>\n</ul>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Testing locally:</b> map the hostname in <code>/etc/hosts</code> → <code>&lt;minikube-ip&gt; demo.local shop.example.com</code>, then plain <code>curl http://shop.example.com/api</code>. No DNS purchased — the Host header does the routing.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Mental model:</b> hosts are <b>apartments in the directory</b>, paths are <b>rooms within them</b>. One edge serves the whole building — the request's Host header is the mailman reading the label.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#ch04\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch06\">next ▶</a></span><span>Page 7</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 06</span><h2 id=\"tls-termination\">🔐 TLS Termination</h2><span class=\"dbadge\">🟡 5 MIN</span></div>\n<p>\"Termination\" = the TLS handshake <b>ends at the ingress</b>. Users get HTTPS; your Pods receive plain HTTP on the internal network. One cert, managed once, at the edge.</p>\n<div class=\"term\"><span class=\"c\">spec</span>:\n  <span class=\"c\">tls</span>:\n  - <span class=\"c\">hosts</span>: [<span class=\"m\">shop.example.com</span>]\n    <span class=\"c\">secretName</span>: <span class=\"y\">shop-tls</span>       <span class=\"g\"># type kubernetes.io/tls (Book 02 · CH 05)</span>\n  <span class=\"c\">rules</span>:\n  - <span class=\"c\">host</span>: <span class=\"m\">shop.example.com</span>\n    <span class=\"c\">http</span>:\n      <span class=\"c\">paths</span>:\n      - <span class=\"c\">path</span>: <span class=\"m\">/</span>\n        <span class=\"c\">pathType</span>: <span class=\"y\">Prefix</span>\n        <span class=\"c\">backend</span>: { <span class=\"c\">service</span>: { <span class=\"c\">name</span>: web-svc, <span class=\"c\">port</span>: { <span class=\"c\">number</span>: <span class=\"y\">80</span> } } }  <span class=\"g\"># plain HTTP here!</span></div>\n<div class=\"term mini\"><span class=\"g\"># the secret the edge serves (self-signed for labs — Lab 2 does it live):</span>\n<span class=\"p\">$</span> openssl req -x509 -nodes -newkey rsa:2048 -days 365 \\\n    <span class=\"y\">-keyout</span> tls.key <span class=\"y\">-out</span> tls.crt <span class=\"y\">-subj</span> <span class=\"m\">\"/CN=shop.example.com\"</span>\n<span class=\"p\">$</span> kubectl create secret tls shop-tls <span class=\"y\">--cert</span>=tls.crt <span class=\"y\">--key</span>=tls.key</div>\n<div class=\"zone zone-net\">\n<div class=\"zlabel\">Termination point</div>\n<div class=\"rowc\">\n<div class=\"kchip\">🌍 HTTPS 🔒</div><span class=\"harr\">──►</span>\n<div class=\"nb c-violet\">Ingress<small>🔒 decrypts here</small></div><span class=\"harr\">──►</span>\n<div class=\"kchip\">HTTP (plain)</div><span class=\"harr\">──►</span>\n<div class=\"pod\">🫛 Pod :80</div>\n</div>\n</div>\n<ul>\n<li>🔁 Re-encryption (HTTPS all the way to Pods) is possible but controller-specific — check before promising \"end-to-end encrypted\" in a security review</li>\n<li>🎟️ Production certs come from cert-manager (Let's Encrypt automation) — same <code>secretName</code> mechanism, the cert just appears</li>\n<li>⚠️ Missing/expired secret named in <code>tls</code> → nginx serves a <b>fake default cert</b>; browsers scream. Diagnose: check the cert issuer, not just the padlock</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> TLS terminates at the edge — the padlock in the user's bar is the Ingress's certificate; inside the cluster, traffic rides the private network as HTTP unless you deliberately re-encrypt.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#ch05\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch07\">next ▶</a></span><span>Page 8</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 07</span><h2 id=\"ingress-controllers\">🧭 Ingress Controllers</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>A controller is a <b>reverse proxy in a Pod</b> + a reconciliation loop: watch Ingress objects → render proxy config → hot-reload. The <code>ingress-nginx</code> controller literally writes an <code>nginx.conf</code> for your rulebook.</p>\n<div class=\"mtree\"><b>Ingress objects</b> <span class=\"g\">(the rulebooks)</span>\n      │ watch\n      ▼\n<b>Controller Pod</b> <span class=\"g\">render config → reload proxy</span>\n      │\n      ▼\n<b>nginx/traefik/haproxy</b> <span class=\"g\">the process actually serving :80/:443</span></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Controller</th><th>Underlying proxy</th><th>Know it for</th></tr>\n<tr><td><b>ingress-nginx</b></td><td>nginx</td><td>the de-facto standard; huge annotation ecosystem; minikube addon</td></tr>\n<tr><td><b>Traefik</b></td><td>traefik (Go)</td><td>CERT-by-default ACME, CRD-native, popular in homelab/k3s</td></tr>\n<tr><td><b>HAProxy</b></td><td>haproxy</td><td>raw TCP performance pedigree</td></tr>\n<tr><td><b>AWS ALB / GCE</b></td><td>managed cloud LB</td><td>Ingress provisions <i>real</i> ALB/GLB instead of in-cluster proxy</td></tr>\n</table></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Annotation culture — power and trap:</b> behavior beyond core routing (rewrites, CORS, IP allowlists, timeouts) arrives via per-controller <b>annotations</b>, e.g. <code>nginx.ingress.kubernetes.io/rewrite-target: /</code>. Powerful — but <b>non-portable</b>: swap controllers and those annotations are silently meaningless. K8s-native versions of some of this live in the Gateway API (CH 13).</div></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Which nginx is which?</b> <code>ingress-nginx</code> = community/kubernetes project. <code>nginx-ingress</code> = F5/NGINX Inc's separate product. Same proxy core, different projects, different annotations — a classic interview gotcha.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> the controller is the muscle behind the rulebook — pick one, pin its <code>IngressClass</code>, and treat its annotations as vendor glue to be minimized.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#ch06\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch08\">next ▶</a></span><span>Page 9</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 08</span><h2 id=\"the-default-allow-world\">🔓 The Default-Allow World</h2><span class=\"dbadge\">🟡 5 MIN</span></div>\n<p>Book 01 built the flat network: every Pod gets a routable IP and — <b>by default — may talk to every other Pod</b>. Frontend to database, and <i>your-laptop-sidecar to database</i>, all equally welcome.</p>\n<div class=\"zone\">\n<div class=\"zlabel\">No NetworkPolicy = zero segmentation</div>\n<div class=\"rowc\">\n<div class=\"pod\">🫛 frontend</div><span class=\"harr\">──►</span>\n<div class=\"pod\">🫛 payment-api</div><span class=\"harr\">──►</span>\n<div class=\"nb c-rose\">🗄️ postgres<small>:5432</small></div>\n</div>\n<div class=\"rowc\">\n<div class=\"kchip\">💀 any compromised pod<small> same rights!</small></div><span class=\"harr\">──►</span>\n<div class=\"nb c-rose\">🗄️ postgres<small>direct line 😱</small></div>\n</div>\n</div>\n<div class=\"table-scroll\"><table>\n<tr><th>Assumption</th><th>Reality</th></tr>\n<tr><td>\"Only my Services can reach my Pods\"</td><td>❌ Services are for <i>discovery</i> — Pod-to-Pod by raw IP works regardless</td></tr>\n<tr><td>\"Namespaces isolate the network\"</td><td>❌ Book 01 · CH 11: namespaces partition <b>names</b>, not traffic — cross-namespace Pod calls flow freely by default</td></tr>\n<tr><td>\"We'd notice lateral movement\"</td><td>❌ nothing logs what was never segmented</td></tr>\n</table></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Why flat-by-default?</b> The IP-per-Pod model promises \"Pods are like hosts on one big network\" — zero-config apps. The price is that <b>security becomes opt-in</b>, via the object the next chapter teaches.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> the Kubernetes network starts as a single open room — <b>any pod, any pod, forever</b> — until a NetworkPolicy walls off a table. Zero-trust here is a YAML you have to write.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#ch07\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch09\">next ▶</a></span><span>Page 10</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 09</span><h2 id=\"networkpolicy-ingress-rules\">🚧 NetworkPolicy — Ingress Rules</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>The grammar in one sentence: <b>\"Pods selected by <code>podSelector</code> may receive connections only from allowed sources, only on allowed ports.\"</b> The instant one policy selects a Pod, default-allow flips to default-deny <i>for that Pod</i>.</p>\n<div class=\"term\"><span class=\"c\">apiVersion</span>: networking.k8s.io/v1\n<span class=\"c\">kind</span>: NetworkPolicy\n<span class=\"c\">metadata</span>:\n  <span class=\"c\">name</span>: allow-frontend-to-api\n  <span class=\"c\">namespace</span>: shop\n<span class=\"c\">spec</span>:\n  <span class=\"c\">podSelector</span>:                 <span class=\"g\"># THE TARGET — who is being protected</span>\n    <span class=\"c\">matchLabels</span>: { <span class=\"c\">app</span>: api }\n  <span class=\"c\">policyTypes</span>: [<span class=\"y\">Ingress</span>]\n  <span class=\"c\">ingress</span>:\n  - <span class=\"c\">from</span>:                       <span class=\"g\"># allowed SOURCES (any of these)</span>\n    - <span class=\"c\">podSelector</span>:             <span class=\"g\"># same-namespace pods with…</span>\n        <span class=\"c\">matchLabels</span>: { <span class=\"c\">app</span>: frontend }\n    - <span class=\"c\">namespaceSelector</span>:       <span class=\"g\"># …OR all pods from matching namespaces</span>\n        <span class=\"c\">matchLabels</span>: { <span class=\"c\">kubernetes.io/metadata.name</span>: monitoring }\n    <span class=\"c\">ports</span>:\n    - { <span class=\"c\">protocol</span>: <span class=\"y\">TCP</span>, <span class=\"c\">port</span>: <span class=\"y\">8080</span> }   <span class=\"g\"># …only this port</span></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>The AND/OR trap (interview favorite):</b> inside <b>one</b> <code>from</code> list item, <code>podSelector</code> + <code>namespaceSelector</code> = <b>AND</b> (pods matching this label <i>in those</i> namespaces). Across <b>separate</b> items = <b>OR</b> (either source). One character of YAML indentation changes the security meaning.</div></div>\n<ul>\n<li>➕ <b>Policies are additive:</b> if two policies select the same Pod, the allowed set is the <b>union</b> — policies can only ever <i>add</i> permission, never subtract</li>\n<li>🎯 Empty <code>podSelector: {}</code> = <b>every Pod in the namespace</b> (no <code>matchLabels</code> field at all)</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Carry the four questions:</b> <i>who's protected (podSelector)? who may call (from)? on what ports? and does a second policy union with this one?</i> — that's 90% of every NetworkPolicy review.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#ch08\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch10\">next ▶</a></span><span>Page 11</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 10</span><h2 id=\"egress-the-default-deny-playbook\">🚫 Egress + The Default-Deny Playbook</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Same grammar, opposite direction. And the industry-standard starting posture: <b>deny everything, then allow named flows.</b></p>\n<div class=\"term\"><span class=\"c\">kind</span>: NetworkPolicy\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: default-deny-all, <span class=\"c\">namespace</span>: shop }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">podSelector</span>: {}              <span class=\"g\"># every pod in shop</span>\n  <span class=\"c\">policyTypes</span>: [<span class=\"y\">Ingress</span>, <span class=\"y\">Egress</span>]\n  <span class=\"c\">ingress</span>: []                  <span class=\"g\"># empty = deny ALL inbound</span>\n  <span class=\"c\">egress</span>: []                   <span class=\"g\"># empty = deny ALL outbound</span></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>The classic default-deny self-own:</b> deny-all <b>egress</b> instantly kills DNS — no pod can resolve <i>anything</i>. The very first egress allow in any cluster is DNS:</div></div>\n<div class=\"term mini\"><span class=\"c\">kind</span>: NetworkPolicy\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: allow-dns }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">podSelector</span>: {}\n  <span class=\"c\">policyTypes</span>: [<span class=\"y\">Egress</span>]\n  <span class=\"c\">egress</span>:\n  - <span class=\"c\">to</span>:\n    - <span class=\"c\">namespaceSelector</span>:\n        <span class=\"c\">matchLabels</span>: { <span class=\"c\">kubernetes.io/metadata.name</span>: <span class=\"y\">kube-system</span> }\n    <span class=\"c\">ports</span>:\n    - { <span class=\"c\">protocol</span>: <span class=\"y\">UDP</span>, <span class=\"c\">port</span>: <span class=\"y\">53</span> }\n    - { <span class=\"c\">protocol</span>: <span class=\"y\">TCP</span>, <span class=\"c\">port</span>: <span class=\"y\">53</span> }</div>\n<h3 id=\"the-production-playbook\">📋 The production playbook</h3>\n<div class=\"rowc\">\n<div class=\"kchip\">1 · default-deny all</div><span class=\"harr\">→</span>\n<div class=\"kchip\">2 · allow DNS :53</div><span class=\"harr\">→</span>\n<div class=\"kchip\">3 · allow app flows<small> frontend→api, api→db</small></div><span class=\"harr\">→</span>\n<div class=\"kchip\">4 · allow ingress-ctrl → apps</div>\n</div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>CNI reality check:</b> NetworkPolicy is just an API — <b>the CNI plugin must enforce it</b>. Calico, Cilium, Weave enforce; <b>flannel does not</b> (policies apply silently, block nothing). If policies \"don't work\", check your CNI before your YAML. Verify with Lab 3, not with hope.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> default-deny + explicit allows = the Kubernetes zero-trust baseline — and rule #1 of deny-all egress is <b>allow DNS first or nothing works and everything looks broken</b>.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#ch09\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch11\">next ▶</a></span><span>Page 12</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 11</span><h2 id=\"coredns-discovery-internals\">📮 CoreDNS — Discovery Internals</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Book 01 asserted \"every Service gets a DNS name.\" Here's the machinery: a <b>CoreDNS Deployment in <code>kube-system</code></b>, fronted by the <code>kube-dns</code> Service — the cluster's phone book.</p>\n<div class=\"mtree\"><b>Pod</b> <span class=\"g\">resolv.conf → nameserver 10.96.0.10</span>\n      │ query: \"v1.default…\"\n      ▼\n<b>kube-dns Service</b> <span class=\"g\">(ClusterIP, stable — dogfooding!)</span>\n      ▼\n<b>CoreDNS Pods</b> <span class=\"g\">watch API Server → build zone in memory</span>\n      ▼\n<span class=\"u\">svc.cluster.local zone</span> <span class=\"g\">every Service &amp; Pod IP, auto</span></div>\n<div class=\"term mini\"><span class=\"g\"># the cluster zone lives in a ConfigMap — the \"Corefile\":</span>\n<span class=\"p\">$</span> kubectl -n kube-system get cm coredns -o yaml\n<span class=\"c\">Corefile</span>: |\n  .:53 {\n      <span class=\"y\">kubernetes</span> cluster.local <span class=\"g\"># ← serves the cluster zone from the API</span>\n      <span class=\"y\">forward</span> . /etc/resolv.conf  <span class=\"g\"># everything else → upstream DNS</span>\n  }</div>\n<div class=\"table-scroll\"><table>\n<tr><th>Query form</th><th>Resolves</th><th>Works from</th></tr>\n<tr><td><code>v1</code></td><td>same namespace</td><td>pods in <code>default</code> (search list fills the rest)</td></tr>\n<tr><td><code>v1.dev</code></td><td>Service <code>v1</code> in ns <code>dev</code></td><td>anywhere</td></tr>\n<tr><td><code>v1.dev.svc.cluster.local</code></td><td>full FQDN</td><td>anywhere (always works)</td></tr>\n</table></div>\n<ul>\n<li>🪄 Zero registration: \"create a Service\" <i>is</i> the DNS record — CoreDNS watches the API, no sidecar config</li>\n<li>🔎 It also serves <b>Pod records</b> (<code>ip-10-244-1-5.default.pod.cluster.local</code>) and <b>SVC/AAAA</b> types — headless Services return Pod IPs directly</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> CoreDNS is a small API-watching DNS server — the reason service discovery needs no setup, and the reason a broken <code>kube-dns</code> Service makes the entire cluster feel dead.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#ch10\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch12\">next ▶</a></span><span>Page 13</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 12</span><h2 id=\"dnspolicy-amp-dns-debugging\">🔧 dnsPolicy &amp; DNS Debugging</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<div class=\"table-scroll\"><table>\n<tr><th>dnsPolicy</th><th>Pod uses…</th><th>When</th></tr>\n<tr><td><code>ClusterFirst</code> <span class=\"stbadge st-comp\">default</span></td><td>CoreDNS (cluster names + forwarded externals)</td><td>99% of Pods</td></tr>\n<tr><td><code>Default</code></td><td>the <b>node's</b> resolv.conf — no cluster names!</td><td>rare; e.g. heavy external-DNS workloads</td></tr>\n<tr><td><code>ClusterFirstWithHostNet</code></td><td>CoreDNS even for hostNetwork Pods</td><td>hostNetwork daemons that still need Service names</td></tr>\n<tr><td><code>None</code></td><td>whatever <code>dnsConfig</code> supplies</td><td>full manual control (custom nameservers/search)</td></tr>\n</table></div>\n<h3 id=\"ndots-5-the-sneaky-perf-tax\">🪤 ndots:5 — the sneaky perf tax</h3>\n<div class=\"term mini\"><span class=\"g\"># a default pod's resolv.conf:</span>\nsearch default.svc.cluster.local svc.cluster.local cluster.local\noptions <span class=\"y\">ndots:5</span>\n<span class=\"g\"># any name with &lt;5 dots is tried AS-IS *and* against every search\n# suffix → \"google.com\" = 1 + 3 = 4 queries. measure, don't guess.</span></div>\n<h3 id=\"the-debug-ladder-lab-4-runs-it-live\">🩺 The debug ladder (Lab 4 runs it live)</h3>\n<div class=\"term\"><span class=\"p\">$</span> kubectl exec dns -- <span class=\"c\">nslookup</span> v1                 <span class=\"g\"># 1 · short name (same ns)</span>\n<span class=\"p\">$</span> kubectl exec dns -- <span class=\"c\">nslookup</span> v1.dev              <span class=\"g\"># 2 · cross-namespace</span>\n<span class=\"p\">$</span> kubectl exec dns -- <span class=\"c\">nslookup</span> kubernetes.default   <span class=\"g\"># 3 · the built-in canary</span>\n<span class=\"p\">$</span> kubectl exec dns -- <span class=\"c\">cat</span> /etc/resolv.conf          <span class=\"g\"># 4 · who's my resolver?</span></div>\n<ul>\n<li>✅ FQDN resolves but short name fails → search list/<code>ndots</code> issue, not DNS death</li>\n<li>✅ nothing resolves + timeouts → check CoreDNS Pods (<code>-n kube-system</code>) and the <code>kube-dns</code> Service endpoints</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> <code>ClusterFirst</code> quietly gives every Pod the cluster phone book plus upstream forwarding — and every \"DNS is down\" incident is solved by the four-command ladder above, in order.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#ch11\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch13\">next ▶</a></span><span>Page 14</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 13</span><h2 id=\"gateway-api-the-successor\">🛣️ Gateway API — The Successor</h2><span class=\"dbadge\">🔵 OVERVIEW</span></div>\n<p>Ingress won the world but shows its age: routing power locked behind <b>vendor annotations</b>, cross-namespace routing unsafe, one blob of YAML mixing infra and app concerns. The <b>Gateway API</b> (SIG-Network, <b>GA since v1.0</b>) is the redesigned successor.</p>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">Ingress (2015 model)</div>\n<ul><li>behavior via per-controller <b>annotations</b> 🩹</li><li>cross-namespace = footgun territory</li><li>platform + app concerns in one object</li><li>not going away — huge installed base</li></ul></div>\n<div class=\"card\"><div class=\"zlabel\">Gateway API</div>\n<ul><li><b>native fields</b> — headers, weights, method routing</li><li>cross-namespace via explicit <code>ReferenceGrant</code></li><li><b>role-split objects</b> (see below)</li><li>portable: any conforming implementation</li></ul></div>\n</div>\n<div class=\"term\"><span class=\"g\"># role separation — the headline idea:</span>\n<span class=\"c\">GatewayClass</span>   <span class=\"g\"># platform team: \"we run nginx-gateway\"</span>\n<span class=\"c\">Gateway</span>        <span class=\"g\"># platform team: listener :443 + TLS cert</span>\n<span class=\"c\">HTTPRoute</span>      <span class=\"g\"># APP team: my host/path → my svc   ← attaches to the Gateway</span>\n<span class=\"g\"># (+ GRPCRoute, TLSRoute… — and app teams never touch LB config)</span></div>\n<div class=\"term mini\"><span class=\"c\">kind</span>: HTTPRoute\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: shop }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">parentRefs</span>: [{ <span class=\"c\">name</span>: edge-gateway }]     <span class=\"g\"># bind to the shared Gateway</span>\n  <span class=\"c\">hostnames</span>: [<span class=\"m\">shop.example.com</span>]\n  <span class=\"c\">rules</span>:\n  - <span class=\"c\">matches</span>: [{ <span class=\"c\">path</span>: { <span class=\"c\">type</span>: <span class=\"y\">PathPrefix</span>, <span class=\"c\">value</span>: <span class=\"m\">/api</span> }}]\n    <span class=\"c\">backendRefs</span>: [{ <span class=\"c\">name</span>: api-svc, <span class=\"c\">port</span>: <span class=\"y\">80</span>, <span class=\"c\">weight</span>: <span class=\"y\">90</span> }]\n  - <span class=\"c\">backendRefs</span>: [{ <span class=\"c\">name</span>: web-svc, <span class=\"c\">port</span>: <span class=\"y\">80</span> }]  <span class=\"g\"># canary: weight 10</span></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Adoption note:</b> needs a Gateway-API controller installed (nginx-gateway, Envoy Gateway, Traefik v3+…). Guidance for new designs: <i>prototype on Ingress today, keep annotations minimal, know your escape hatch is Gateway API</i> — Book 08's GitOps tooling speaks both.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> Gateway API keeps Ingress's job but fixes its politics — <b>infrastructure (Gateway) owned by platform teams, routes (HTTPRoute) owned by app teams</b>, with portability and canary weights as first-class citizens.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#ch12\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab1\">labs ▶</a></span><span>Page 15</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 1</span><h2 id=\"path-routing-via-ingress\">🔬 Path Routing via Ingress</h2><span class=\"dbadge\">🟠 15 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · Controller + two apps</div>\n<div class=\"term mini\"><span class=\"p\">$</span> minikube addons enable ingress\n<span class=\"p\">$</span> kubectl create deploy v1 --image=hashicorp/http-echo -- <span class=\"y\">-text</span>=hello-v1\n<span class=\"p\">$</span> kubectl create deploy v2 --image=hashicorp/http-echo -- <span class=\"y\">-text</span>=hello-v2\n<span class=\"p\">$</span> kubectl expose deploy v1 --port=5678 &amp;&amp; kubectl expose deploy v2 --port=5678\n<span class=\"g\"># printf-style echo servers: perfect for proving WHO answered</span></div></div>\n<div class=\"labstep\"><div>STEP 2 · The rulebook</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl apply -f - <span class=\"c\">&lt;&lt;EOF</span>\n<span class=\"c\">apiVersion</span>: networking.k8s.io/v1\n<span class=\"c\">kind</span>: Ingress\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: routes }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">ingressClassName</span>: nginx\n  <span class=\"c\">rules</span>:\n  - <span class=\"c\">host</span>: demo.local\n    <span class=\"c\">http</span>:\n      <span class=\"c\">paths</span>:\n      - { <span class=\"c\">path</span>: <span class=\"m\">/v1</span>, <span class=\"c\">pathType</span>: <span class=\"y\">Prefix</span>,\n          <span class=\"c\">backend</span>: { <span class=\"c\">service</span>: { <span class=\"c\">name</span>: v1, <span class=\"c\">port</span>: { <span class=\"c\">number</span>: <span class=\"y\">5678</span> } } } }\n      - { <span class=\"c\">path</span>: <span class=\"m\">/v2</span>, <span class=\"c\">pathType</span>: <span class=\"y\">Prefix</span>,\n          <span class=\"c\">backend</span>: { <span class=\"c\">service</span>: { <span class=\"c\">name</span>: v2, <span class=\"c\">port</span>: { <span class=\"c\">number</span>: <span class=\"y\">5678</span> } } } }\n<span class=\"c\">EOF</span></div>\n<p>Add to <code>/etc/hosts</code> (admin): <code>&lt;minikube ip&gt; demo.local</code></p></div>\n<div class=\"grid2\">\n<div class=\"tabwin\"><div class=\"tabhead\">👀 TEST</div><div class=\"tabbody\"><span class=\"p\">$</span> curl demo.local/v1\n<span class=\"p\">hello-v1</span>\n<span class=\"p\">$</span> curl demo.local/v2\n<span class=\"p\">hello-v2</span>  <span class=\"g\"># path → service, proven</span>\n<span class=\"p\">$</span> curl demo.local/v1/extra\n<span class=\"p\">hello-v1</span>  <span class=\"g\"># Prefix catches subpaths</span></div></div>\n<div class=\"tabwin\"><div class=\"tabhead\">🔍 PROOF IT'S L7</div><div class=\"tabbody\"><span class=\"g\"># same port 80 for both —\n# only the PATH differed.\n# A NodePort could never do\n# this without 2 services\n# on 2 ports.</span></div></div>\n</div>\n<p><b>Teardown:</b> <code>kubectl delete ingress routes &amp;&amp; kubectl delete deploy v1 v2 &amp;&amp; kubectl delete svc v1 v2</code></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#ch13\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab2\">next ▶</a></span><span>Page 16</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 2</span><h2 id=\"tls-on-an-ingress\">🔐 TLS on an Ingress</h2><span class=\"dbadge\">🟠 10 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · Cert + Secret (Book 02 · CH 05 in action)</div>\n<div class=\"term mini\"><span class=\"p\">$</span> openssl req -x509 -nodes -newkey rsa:2048 -days 365 \\\n    <span class=\"y\">-keyout</span> tls.key <span class=\"y\">-out</span> tls.crt <span class=\"y\">-subj</span> <span class=\"m\">\"/CN=demo.local\"</span>\n<span class=\"p\">$</span> kubectl create secret tls demo-tls <span class=\"y\">--cert</span>=tls.crt <span class=\"y\">--key</span>=tls.key</div></div>\n<div class=\"labstep\"><div>STEP 2 · Add the tls block to the Lab 1 Ingress</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl patch ingress routes <span class=\"y\">--type</span>=merge <span class=\"y\">-p</span> \\\n  <span class=\"m\">'{\"spec\":{\"tls\":[{\"hosts\":[\"demo.local\"],\"secretName\":\"demo-tls\"}]}}'</span>\n<span class=\"p\">$</span> kubectl get ingress routes\n<span class=\"y\">HOSTS     PORTS     AGE</span>\ndemo.local  <span class=\"p\">80, 443</span>  <span class=\"g\"># 443 appeared</span></div></div>\n<div class=\"grid2\">\n<div class=\"tabwin\"><div class=\"tabhead\">👀 TEST HTTPS</div><div class=\"tabbody\"><span class=\"p\">$</span> curl -<span class=\"y\">k</span> https://demo.local/v1\n<span class=\"p\">hello-v1</span>  <span class=\"g\"># works! (-k: self-signed)</span></div></div>\n<div class=\"tabwin\"><div class=\"tabhead\">🔍 INSPECT THE CERT</div><div class=\"tabbody\"><span class=\"p\">$</span> curl -kv https://demo.local 2&gt;&amp;1 | <span class=\"c\">grep</span> subject\n<span class=\"y\">subject: CN=demo.local</span>\n<span class=\"g\"># the EDGE serves your secret —\n# pods never saw a cert</span></div></div>\n</div>\n<p><b>Proved:</b> termination happens at the Ingress (CH 06) — one self-signed secret, HTTPS at the edge, plain HTTP behind. <b>Teardown:</b> Lab 1 teardown + <code>kubectl delete secret demo-tls</code>.</p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#lab1\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab3\">next ▶</a></span><span>Page 17</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 3</span><h2 id=\"default-deny-selective-allow\">🚧 Default-Deny → Selective Allow</h2><span class=\"dbadge\">🟠 12 MIN · HANDS-ON</span></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>CNI check first:</b> minikube default (bridge/kindnet) does <b>not</b> enforce policies. Restart with Calico, or run this lab on a cluster whose CNI enforces: <code>minikube delete &amp;&amp; minikube start --cni=calico</code>.</div></div>\n<div class=\"labstep\"><div>STEP 1 · Players: a server, a labeled client, an unlabeled client</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl create deploy v1 --image=hashicorp/http-echo -- <span class=\"y\">-text</span>=hello-v1\n<span class=\"p\">$</span> kubectl expose deploy v1 --port=5678\n<span class=\"p\">$</span> kubectl run client --image=busybox:1.36 --restart=Never -- sleep 9999\n<span class=\"p\">$</span> kubectl run stranger --image=busybox:1.36 --restart=Never -- sleep 9999</div></div>\n<div class=\"labstep\"><div>STEP 2 · Deny all ingress to v1</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl apply -f - <span class=\"c\">&lt;&lt;EOF</span>\n<span class=\"c\">apiVersion</span>: networking.k8s.io/v1\n<span class=\"c\">kind</span>: NetworkPolicy\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: deny-v1 }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">podSelector</span>: { <span class=\"c\">matchLabels</span>: { <span class=\"c\">app</span>: v1 } }\n  <span class=\"c\">policyTypes</span>: [<span class=\"y\">Ingress</span>]\n  <span class=\"c\">ingress</span>: []\n<span class=\"c\">EOF</span>\n<span class=\"p\">$</span> kubectl exec client -- <span class=\"c\">wget</span> -qO- -T 3 http://v1:5678\n<span class=\"r\">wget: download timed out</span>  <span class=\"g\"># ← BLOCKED. the room has a wall.</span></div></div>\n<div class=\"labstep\"><div>STEP 3 · Allow only labeled callers</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl apply -f - <span class=\"c\">&lt;&lt;EOF</span>\n<span class=\"c\">apiVersion</span>: networking.k8s.io/v1\n<span class=\"c\">kind</span>: NetworkPolicy\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: allow-labeled }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">podSelector</span>: { <span class=\"c\">matchLabels</span>: { <span class=\"c\">app</span>: v1 } }\n  <span class=\"c\">ingress</span>:\n  - <span class=\"c\">from</span>: [{ <span class=\"c\">podSelector</span>: { <span class=\"c\">matchLabels</span>: { <span class=\"c\">access</span>: <span class=\"m\">\"true\"</span> } } }]\n<span class=\"c\">EOF</span>\n<span class=\"p\">$</span> kubectl label pod client access=true\n<span class=\"p\">$</span> kubectl exec client -- <span class=\"c\">wget</span> -qO- http://v1:5678   <span class=\"g\"># now labeled</span>\n<span class=\"p\">hello-v1</span>  <span class=\"g\"># ✅ allowed</span>\n<span class=\"p\">$</span> kubectl exec stranger -- <span class=\"c\">wget</span> -qO- -T 3 http://v1:5678\n<span class=\"r\">wget: download timed out</span>  <span class=\"g\"># ❌ still denied — labels are the keys</span></div></div>\n<p><b>Proved:</b> policy selects the server; pod labels select the callers; union of policies; enforcement is CNI-dependent. <b>Teardown:</b> <code>kubectl delete np deny-v1 allow-labeled &amp;&amp; kubectl delete pod client stranger &amp;&amp; kubectl delete deploy v1 &amp;&amp; kubectl delete svc v1</code></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#lab2\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab4\">next ▶</a></span><span>Page 18</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 4</span><h2 id=\"dns-debugging-from-inside-a-pod\">📮 DNS Debugging from Inside a Pod</h2><span class=\"dbadge\">🟠 8 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · The debug pod + the ladder</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl run dns --image=busybox:1.36 --restart=Never -- sleep 9999\n<span class=\"p\">$</span> kubectl exec dns -- <span class=\"c\">nslookup</span> kubernetes.default\n<span class=\"y\">Server:    10.96.0.10</span>  <span class=\"g\"># ← CoreDNS via kube-dns Service</span>\n<span class=\"y\">Name:      kubernetes.default.svc.cluster.local</span>\n<span class=\"y\">Address:   10.96.0.1</span>   <span class=\"g\"># ← the API Server's ClusterIP</span></div></div>\n<div class=\"grid2\">\n<div class=\"tabwin\"><div class=\"tabhead\">👀 NAME FORMS</div><div class=\"tabbody\"><span class=\"p\">$</span> kubectl exec dns -- nslookup <span class=\"p\">kubernetes</span>\n<span class=\"g\"># ✅ short name (same ns)</span>\n<span class=\"p\">$</span> kubectl exec dns -- nslookup <span class=\"p\">kube-dns.kube-system</span>\n<span class=\"g\"># ✅ ns-qualified</span>\n<span class=\"p\">$</span> kubectl exec dns -- nslookup \\\n  <span class=\"p\">kube-dns.kube-system.svc.cluster.local</span>\n<span class=\"g\"># ✅ full FQDN — always works</span></div></div>\n<div class=\"tabwin\"><div class=\"tabhead\">🔍 WHO CONFIGURED ME?</div><div class=\"tabbody\"><span class=\"p\">$</span> kubectl exec dns -- <span class=\"c\">cat</span> /etc/resolv.conf\n<span class=\"c\">nameserver 10.96.0.10</span>\n<span class=\"y\">search default.svc.cluster.local\n      svc.cluster.local cluster.local</span>\n<span class=\"y\">options ndots:5</span>\n<span class=\"g\"># dnsPolicy ClusterFirst wrote\n# this file at pod start — CH 12</span></div></div>\n</div>\n<p><b>Proved:</b> short names ride the search list; the resolver is the stable <code>kube-dns</code> VIP; <code>ndots:5</code> is why \"external domains feel slow\" (CH 12's perf tax). <b>Teardown:</b> <code>kubectl delete pod dns</code>.</p>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Interview habit unlocked:</b> when someone says \"DNS is broken in the cluster,\" you now open with <code>kubectl exec … nslookup kubernetes.default</code> — the canary that separates cluster-DNS death from an app's bad name.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#lab3\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#quiz\">quiz ▶</a></span><span>Page 19</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">QUIZ</span><h2 id=\"self-check-quiz\">✅ Self-Check Quiz</h2><span class=\"dbadge\">☑ 10 questions</span></div>\n<div class=\"qz\"><span class=\"qn\">Q1.</span>A LoadBalancer Service, examined closely, routes traffic to Pods via which underlying mechanism?<br /><b>A.</b> NodePorts on every node   <b>B.</b> Direct Pod IP registration   <b>C.</b> Ingress rules   <b>D.</b> HostNetwork daemons</div>\n<div class=\"qz\"><span class=\"qn\">Q2.</span>You apply an Ingress to a cluster with no controller installed. Result?<br /><b>A.</b> Apply fails with a validation error   <b>B.</b> Ingress is created and works over NodePort fallback   <b>C.</b> Ingress is created but silently does nothing — no ADDRESS ever appears   <b>D.</b> The API Server starts a default controller</div>\n<div class=\"qz\"><span class=\"qn\">Q3.</span>Which <code>pathType</code> matches <code>/api</code> <i>and</i> <code>/api/v1/users</code>?<br /><b>A.</b> Exact   <b>B.</b> Prefix   <b>C.</b> Whole   <b>D.</b> Regex</div>\n<div class=\"qz\"><span class=\"qn\">Q4.</span>An Ingress <code>tls</code> entry's <code>secretName</code> must reference a Secret of which type?<br /><b>A.</b> Opaque   <b>B.</b> kubernetes.io/tls with tls.crt + tls.key   <b>C.</b> dockerconfigjson   <b>D.</b> basic-auth</div>\n<div class=\"qz\"><span class=\"qn\">Q5.</span>NetworkPolicies apply but block nothing. Most likely cause?<br /><b>A.</b> Missing ingressClassName   <b>B.</b> Policies need a namespace label   <b>C.</b> The CNI (e.g. flannel) doesn't enforce NetworkPolicy   <b>D.</b> policyTypes omitted</div>\n<div class=\"qz\"><span class=\"qn\">Q6.</span>A NetworkPolicy has <code>podSelector: {}</code> and empty <code>ingress: []</code>. It affects…<br /><b>A.</b> every Pod in that namespace   <b>B.</b> only unlabeled Pods   <b>C.</b> the whole cluster   <b>D.</b> nothing — empty selector is invalid</div>\n<div class=\"qz\"><span class=\"qn\">Q7.</span>Two NetworkPolicies both select Pod X with different allow rules. X's effective access is…<br /><b>A.</b> the intersection (both must match)   <b>B.</b> the last-applied policy only   <b>C.</b> the first-created policy only   <b>D.</b> the union — policies only ever add permission</div>\n<div class=\"qz\"><span class=\"qn\">Q8.</span>The FQDN of Service <code>web</code> in namespace <code>prod</code> is…<br /><b>A.</b> web.prod.local   <b>B.</b> prod.web.svc.k8s   <b>C.</b> web-svc.prod.default   <b>D.</b> web.prod.svc.cluster.local</div>\n<div class=\"qz\"><span class=\"qn\">Q9.</span>With <code>dnsPolicy: Default</code>, a Pod resolves names using…<br /><b>A.</b> CoreDNS like everyone   <b>B.</b> the node's own resolv.conf — cluster Service names fail   <b>C.</b> hardcoded 8.8.8.8   <b>D.</b> the kubelet's cache</div>\n<div class=\"qz\"><span class=\"qn\">Q10.</span>In Gateway API, which object carries the app team's routing rules?<br /><b>A.</b> Gateway   <b>B.</b> GatewayClass   <b>C.</b> HTTPRoute   <b>D.</b> IngressClass</div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#lab4\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#key\">answers ▶</a></span><span>Page 20</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">KEY</span><h2 id=\"answer-key-scoring\">🗝️ Answer Key + Scoring</h2><span class=\"dbadge\">grade yourself</span></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Q</th><th>Ans</th><th>Why — one line</th></tr>\n<tr><td>1</td><td><b>A</b></td><td>LB is NodePort + cloud wallet — the port column betrays it (CH 01–02)</td></tr>\n<tr><td>2</td><td><b>C</b></td><td>Ingress = rulebook; no referee, no game, no error (CH 04)</td></tr>\n<tr><td>3</td><td><b>B</b></td><td>Prefix matches the segment and everything under it (CH 05)</td></tr>\n<tr><td>4</td><td><b>B</b></td><td>tls type mandates tls.crt/tls.key keys — Book 02 · CH 05 (CH 06)</td></tr>\n<tr><td>5</td><td><b>C</b></td><td>Policy is an API; enforcement lives in the CNI — flannel won't (CH 10, Lab 3)</td></tr>\n<tr><td>6</td><td><b>A</b></td><td>Empty selector = all Pods in the namespace; empty rules = deny (CH 09–10)</td></tr>\n<tr><td>7</td><td><b>D</b></td><td>Additive union — policies grant, never revoke (CH 09)</td></tr>\n<tr><td>8</td><td><b>D</b></td><td>&lt;svc&gt;.&lt;ns&gt;.svc.cluster.local — CH 11</td></tr>\n<tr><td>9</td><td><b>B</b></td><td>Default = node's resolver; cluster names don't exist for that Pod (CH 12)</td></tr>\n<tr><td>10</td><td><b>C</b></td><td>Gateway = shared listener; HTTPRoute = app-owned rules (CH 13)</td></tr>\n</table></div>\n<div class=\"grid3\">\n<div class=\"card center\"><div>🏆</div><p><b>9–10</b><br />Ready for Book 04</p></div>\n<div class=\"card center\"><div>📖</div><p><b>6–8</b><br />Re-read missed chapters' 🔑 boxes</p></div>\n<div class=\"card center\"><div>🔁</div><p><b>&lt;6</b><br />Re-run Labs 1–4, then retake</p></div>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Missed Q5 or Q7?</b> Those are the two production incidents-in-waiting: unenforcing CNI (false security) and the additive-union rule (false restriction). Missed Q2? Remember: <i>apply succeeds ≠ traffic flows</i>.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#quiz\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#gloss\">next ▶</a></span><span>Page 21</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">GLOSS</span><h2 id=\"glossary\">📚 Glossary</h2><span class=\"dbadge\">🔵 REFERENCE</span></div>\n<div class=\"gl\"><b>Exposition ladder</b> — ClusterIP → NodePort → LoadBalancer; each rung delegates to the one below.</div>\n<div class=\"gl\"><b>LoadBalancer</b> — Service type; a cloud controller provisions an external LB fronting NodePorts. One per Service = one bill per Service.</div>\n<div class=\"gl\"><b>MetalLB / minikube tunnel</b> — ways to get LB behavior without a cloud (bare metal / local dev).</div>\n<div class=\"gl\"><b>Ingress</b> — L7 routing rulebook (host/path → Service); inert without a controller.</div>\n<div class=\"gl\"><b>IngressClass</b> — named controller type; <code>spec.ingressClassName</code> binds an Ingress to its referee.</div>\n<div class=\"gl\"><b>Ingress Controller</b> — running reverse proxy (ingress-nginx, Traefik…) that watches Ingress objects and renders live proxy config.</div>\n<div class=\"gl\"><b>pathType</b> — Prefix (segment + subtree) / Exact (literal) / ImplementationSpecific.</div>\n<div class=\"gl\"><b>TLS termination</b> — HTTPS ends at the Ingress; Pod traffic is plain HTTP unless re-encrypted deliberately.</div>\n<div class=\"gl\"><b>Annotation</b> — controller-specific behavior knob (rewrites, CORS…); powerful, non-portable.</div>\n<div class=\"gl\"><b>NetworkPolicy</b> — namespaced firewall rules: podSelector (target) + ingress/egress (from/to/ports); additive union; CNI-enforced.</div>\n<div class=\"gl\"><b>Default-deny</b> — posture where a selected Pod receives/sends nothing unless a policy allows it; empty rules array = deny all.</div>\n<div class=\"gl\"><b>ipBlock / namespaceSelector / podSelector (in from/to)</b> — the three source/destination selector types.</div>\n<div class=\"gl\"><b>CoreDNS</b> — cluster DNS Deployment in kube-system behind the kube-dns Service; serves svc.cluster.local by watching the API.</div>\n<div class=\"gl\"><b>FQDN of a Service</b> — &lt;name&gt;.&lt;namespace&gt;.svc.cluster.local; short names rely on the search list.</div>\n<div class=\"gl\"><b>ndots:5</b> — resolv.conf option causing search-list expansion; the hidden cost behind \"slow external names\".</div>\n<div class=\"gl\"><b>dnsPolicy</b> — ClusterFirst (default) / Default (node's resolver) / ClusterFirstWithHostNet / None + dnsConfig.</div>\n<div class=\"gl\"><b>Gateway API</b> — GA successor to Ingress: GatewayClass + Gateway (platform-owned) and HTTPRoute (app-owned), portable and cross-namespace-safe via ReferenceGrant.</div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#key\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#cheat\">next ▶</a></span><span>Page 22</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CHEAT</span><h2 id=\"one-page-cheat-sheet\">📄 One-Page Cheat Sheet</h2><span class=\"dbadge\">🔵 print me</span></div>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">🌐 Traffic — commands</div><div class=\"term mini\"><span class=\"p\">$</span> minikube addons enable ingress\n<span class=\"p\">$</span> kubectl get ingressclass\n<span class=\"p\">$</span> kubectl get ingress  <span class=\"g\"># ADDRESS must appear!</span>\n<span class=\"p\">$</span> kubectl create secret tls t --cert=c --key=k\n<span class=\"p\">$</span> curl -k https://demo.local/api\n<span class=\"g\"># /etc/hosts: &lt;minikube ip&gt; demo.local</span></div></div>\n<div class=\"card\"><div class=\"zlabel\">📮 DNS — debug ladder</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl run dns --image=busybox:1.36 -it --rm \\\n   --restart=Never -- nslookup <span class=\"y\">kubernetes.default</span>\n<span class=\"p\">$</span> … nslookup svc.ns.svc.cluster.local\n<span class=\"p\">$</span> kubectl exec dns -- cat /etc/resolv.conf\n<span class=\"g\"># kube-dns VIP = 10.96.0.10 by default</span></div></div>\n</div>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">🚧 Default-deny skeleton</div><div class=\"term mini\"><span class=\"c\">podSelector</span>: {}\n<span class=\"c\">policyTypes</span>: [Ingress, Egress]\n<span class=\"c\">ingress</span>: []  <span class=\"g\"># deny in</span>\n<span class=\"c\">egress</span>: []   <span class=\"g\"># deny out</span>\n<span class=\"g\"># FIRST allow: DNS udp+tcp 53 → kube-system\n# policies are ADDITIVE (union)\n# CNI must enforce (calico/cilium, NOT flannel)</span></div></div>\n<div class=\"card\"><div class=\"zlabel\">🪜 Ladder + rules of thumb</div><div class=\"table-scroll\"><table><tr><th>Need</th><th>Reach for</th></tr><tr><td>internal only</td><td>ClusterIP</td></tr><tr><td>quick demo, one app</td><td>NodePort</td></tr><tr><td>the one edge / TCP thing</td><td>LoadBalancer</td></tr><tr><td>HTTP host/path routing</td><td>Ingress</td></tr><tr><td>portable, canary, multi-team</td><td>Gateway API</td></tr></table></div></div>\n</div>\n<div class=\"card\"><div class=\"zlabel\">🧠 Facts worth a job offer</div>\n<ul>\n<li>LB = NodePort underneath · Ingress without controller = silently dead (check ADDRESS + ingressclass)</li>\n<li>TLS terminates at the edge; Pods stay HTTP unless deliberately re-encrypted</li>\n<li>Annotations are vendor glue — Gateway API is the portable successor (GA v1.0)</li>\n<li>NetworkPolicy: additive union · empty selector = whole namespace · empty rules = deny · AND within a from-item, OR across items</li>\n<li>Deny-all egress kills DNS first — always allow :53 to kube-system</li>\n<li>CoreDNS = API-watching DNS behind kube-dns VIP · ndots:5 = why external lookups multiply</li>\n</ul></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#gloss\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#finale\">finale ▶</a></span><span>Page 23</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">FINALE</span><h2 id=\"what-you-can-do-now\">🗺️ What You Can Do Now</h2><span class=\"dbadge\">🎓 Book 03 complete</span></div>\n<p>Book 01 built the machine, Book 02 dressed it — this book gave it <b>a front door, a phone book, and locks between the rooms</b>.</p>\n<div class=\"mtree\"><b>🌐 TRAFFIC — fully mapped:</b>\n├── <u>Ladder</u>         <span class=\"g\">ClusterIP → NodePort → LB (each rung delegates)</span>\n├── <u>Ingress</u>        <span class=\"g\">host/path rules → Services · TLS at the edge</span>\n├── <u>Controller</u>     <span class=\"g\">the proxy that enforces the rulebook</span>\n├── <u>NetworkPolicy</u>  <span class=\"g\">default-deny → explicit allows (DNS first!)</span>\n├── <u>CoreDNS</u>        <span class=\"g\">svc.cluster.local · ndots · dnsPolicy</span>\n└── <u>Gateway API</u>    <span class=\"g\">the portable future (Gateway + HTTPRoute)</span></div>\n<h3 id=\"you-can-now\">✅ You can now…</h3>\n<ul>\n<li>Choose the right rung per Service — and explain the cost of picking wrong</li>\n<li>Ship production Ingress: host/path rules, TLS secrets, controller triage (no ADDRESS? no controller)</li>\n<li>Write a default-deny NetworkPolicy set that doesn't strangle DNS — and prove enforcement on the real CNI</li>\n<li>Debug any \"DNS broken\" report with a four-command ladder instead of vibes</li>\n<li>Place Gateway API in the roadmap and say precisely what it fixes about Ingress</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🎓</span><div><b>Where to next — Book 04 · Scheduling &amp; Node Management:</b> your traffic arrives at the right door now — Book 04 decides <b>which machines run what</b>: the full taints/tolerations system, node &amp; pod affinity, topology spread, Priority &amp; Preemption, cordon/drain maintenance, and static Pods. You already tasted taints in Book 01's Lab 5 — now we master the whole discipline.</div></div>\n<div class=\"center\">— End of Book 03 · 🎬 —</div>\n<div class=\"pgfoot\"><span>📘 Book 03 · Services &amp; Networking</span><span><a href=\"#cheat\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a></span><span>Page 24</span></div></div>\n\n\n","toc":[{"id":"services-amp-networking","text":"SERVICES &amp;NETWORKING","level":1},{"id":"contents-click-any-row","text":"Contents — click any row","level":2},{"id":"the-exposition-ladder","text":"🪜 The Exposition Ladder","level":2},{"id":"loadbalancer-the-cloud-type","text":"⚖️ LoadBalancer — The Cloud Type","level":2},{"id":"what-actually-happens-on-apply","text":"🌩️ What actually happens on apply","level":3},{"id":"the-problem-ingress-solves","text":"💡 The Problem Ingress Solves","level":2},{"id":"ingress-amp-ingressclass","text":"🚦 Ingress &amp; IngressClass","level":2},{"id":"host-amp-path-routing","text":"🛣️ Host &amp; Path Routing","level":2},{"id":"tls-termination","text":"🔐 TLS Termination","level":2},{"id":"ingress-controllers","text":"🧭 Ingress Controllers","level":2},{"id":"the-default-allow-world","text":"🔓 The Default-Allow World","level":2},{"id":"networkpolicy-ingress-rules","text":"🚧 NetworkPolicy — Ingress Rules","level":2},{"id":"egress-the-default-deny-playbook","text":"🚫 Egress + The Default-Deny Playbook","level":2},{"id":"the-production-playbook","text":"📋 The production playbook","level":3},{"id":"coredns-discovery-internals","text":"📮 CoreDNS — Discovery Internals","level":2},{"id":"dnspolicy-amp-dns-debugging","text":"🔧 dnsPolicy &amp; DNS Debugging","level":2},{"id":"ndots-5-the-sneaky-perf-tax","text":"🪤 ndots:5 — the sneaky perf tax","level":3},{"id":"the-debug-ladder-lab-4-runs-it-live","text":"🩺 The debug ladder (Lab 4 runs it live)","level":3},{"id":"gateway-api-the-successor","text":"🛣️ Gateway API — The Successor","level":2},{"id":"path-routing-via-ingress","text":"🔬 Path Routing via Ingress","level":2},{"id":"tls-on-an-ingress","text":"🔐 TLS on an Ingress","level":2},{"id":"default-deny-selective-allow","text":"🚧 Default-Deny → Selective Allow","level":2},{"id":"dns-debugging-from-inside-a-pod","text":"📮 DNS Debugging from Inside a Pod","level":2},{"id":"self-check-quiz","text":"✅ Self-Check Quiz","level":2},{"id":"answer-key-scoring","text":"🗝️ Answer Key + Scoring","level":2},{"id":"glossary","text":"📚 Glossary","level":2},{"id":"one-page-cheat-sheet","text":"📄 One-Page Cheat Sheet","level":2},{"id":"what-you-can-do-now","text":"🗺️ What You Can Do Now","level":2},{"id":"you-can-now","text":"✅ You can now…","level":3}],"words":5978,"assets":[]};